const wallets = { 1: 1000, 2: 1000 };

function transaction(work) {
  const draft = { ...wallets };
  work(draft);
  Object.assign(wallets, draft);
}

function transfer(from, to, amount) {
  try {
    transaction((tx) => {
      if (!(from in tx) || tx[from] < amount) throw new Error("409");
      tx[from] -= amount;
      if (!(to in tx)) throw new Error("404");
      tx[to] += amount;
    });
    return 200;
  } catch (error) {
    return Number(error.message);
  }
}

