const LOCK_MS = 15 * 60_000;
const state = new Map();

function recordFailure(userId, now) {
  const entry = state.get(userId) ?? { failures: 0, lockedUntil: 0 };
  entry.failures += 1;
  if (entry.failures >= 10) {
    entry.lockedUntil = now + LOCK_MS;
    entry.failures = 0;
  }
  state.set(userId, entry);
}

function isLocked(userId, now) {
  const entry = state.get(userId);
  return entry !== undefined && now < entry.lockedUntil;
}

for (let i = 0; i < 9; i++) recordFailure(1, 1000);
const afterNine = isLocked(1, 1000);
recordFailure(1, 2000);
console.log(afterNine, isLocked(1, 2000), isLocked(1, 2000 + LOCK_MS - 1), isLocked(1, 2000 + LOCK_MS));

