let db = { wallets: { 1: 1000, 2: 1000 }, ledger: [] };

function transfer(from, to, amount) {
  const tx = { wallets: { ...db.wallets }, ledger: [...db.ledger] };
  tx.wallets[from] -= amount;
  if (!(to in tx.wallets)) throw new Error("No wallet");
  tx.wallets[to] += amount;
  tx.ledger.push({ from, to, amount });
  db = tx;
}

transfer(1, 2, 500);
try {
  transfer(1, 99, 100);
} catch {}
console.log("ledger:", db.ledger.length, "wallets:", db.wallets[1], db.wallets[2]);

